yaml_example:
- if: ${{ params.amount }} > 1000
  steps:
    - run: set
      with: { tier: review }
  else:
    - if: ${{ params.vip }}
      run: set
      with: { tier: priority }
      else:
        - run: set
          with: { tier: standard }
- run: respond
  with: { status: 200, json: { tier: "${{ tier }}" } }
